{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "AKBA, an acetylated triterpene carboxylic acid, has poor oral bioavailability in healthy volunteers due to low absorption and/or extensive metabolism; this is the closest functional analogue to the query's terpenoid acid/acetate motif and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Medroxyprogesterone acetate, a steroid acetate, has oral bioavailability below 15% in humans, supporting that acetate-bearing lipophilic terpenoid/steroid cores can undergo extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ursodeoxycholic acid, a steroid carboxylic acid with hydroxyls, shows 78-87% systemic availability, demonstrating that some steroid-like acids are well absorbed; however, this relies on bile-acid transporter/enterohepatic mechanisms not present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "16-acetyl-gitoxin, an acetylated cardiac glycoside, has ~98.6% oral bioavailability in healthy volunteers, showing that acetylation does not preclude high F; but its glycoside structure is distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability (<20%) based on closest functional analogues (acetylated terpenoid acids/steroid acetates) showing poor F; high-F bile acid/cardiac glycoside analogues are less transferable due to active transport/glycoside features.",
  "evidence_gaps": [
    "No close structural analogue (Morgan similarity >0.3) is available.",
    "No direct pharmacokinetic data exist for this diterpenoid acid scaffold.",
    "Solubility, permeability, and first-pass metabolism of the query are unknown.",
    "Potential involvement of bile-acid transporters or enterohepatic recirculation is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

